import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  SetIssueParentInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type {
  Issue,
  IssueBoardColumn,
  IssueRollup,
  IssueWithRelations,
} from "@/types/issue";
import type { Actor } from "@/types/member";

/** Depth of an issue in its tree; a root issue (no parent) is level 0. */
function depthOf(issue: Issue, byId: ReadonlyMap<IssueId, Issue>): number {
  let depth = 0;
  let cursor: Issue | undefined = issue;
  while (cursor?.parentId) {
    const next: Issue | undefined = byId.get(cursor.parentId);
    if (!next) break;
    depth++;
    cursor = next;
  }
  return depth;
}

/** How many extra levels exist below `issueId`; 0 for a leaf. */
function maxDepthBelow(issueId: IssueId, all: readonly Issue[]): number {
  const childrenByParent = new Map<IssueId, Issue[]>();
  for (const issue of all) {
    if (issue.parentId !== null) {
      const siblings = childrenByParent.get(issue.parentId) ?? [];
      siblings.push(issue);
      childrenByParent.set(issue.parentId, siblings);
    }
  }

  function height(id: IssueId): number {
    const children = childrenByParent.get(id) ?? [];
    if (children.length === 0) return 0;
    return 1 + Math.max(...children.map((child) => height(child.id)));
  }

  return height(issueId);
}

/** Every issue below `rootId`, at any depth, drawn from `all`. */
function collectDescendants(
  rootId: IssueId,
  all: readonly Issue[],
): readonly Issue[] {
  const childrenByParent = new Map<IssueId, Issue[]>();
  for (const issue of all) {
    if (issue.parentId !== null) {
      const siblings = childrenByParent.get(issue.parentId) ?? [];
      siblings.push(issue);
      childrenByParent.set(issue.parentId, siblings);
    }
  }

  const result: Issue[] = [];
  const queue: Issue[] = [...(childrenByParent.get(rootId) ?? [])];
  while (queue.length > 0) {
    const current = queue.shift();
    if (!current) continue;
    result.push(current);
    queue.push(...(childrenByParent.get(current.id) ?? []));
  }
  return result;
}

/**
 * Validates a prospective parent: live, same project, no cycle and no
 * resulting depth beyond `MAX_SUB_ISSUE_DEPTH`. `movingIssueId` is `null` at
 * creation time, when there is no existing id and no subtree to carry along.
 */
async function assertValidParentPlacement(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
  movingIssueId: IssueId | null,
): Promise<void> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);

  const all = await issueRepo.listAllInProject(orgId, projectId);
  const byId = new Map(all.map((issue) => [issue.id, issue]));

  if (movingIssueId !== null) {
    let cursor: Issue | undefined = parent;
    while (cursor) {
      if (cursor.id === movingIssueId) {
        throw new IssueHierarchyError(movingIssueId, "cycle");
      }
      cursor = cursor.parentId ? byId.get(cursor.parentId) : undefined;
    }
  }

  const parentDepth = depthOf(parent, byId);
  const subtreeHeight =
    movingIssueId === null ? 0 : maxDepthBelow(movingIssueId, all);
  if (parentDepth + 1 + subtreeHeight > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(movingIssueId ?? parentId, "too_deep");
  }
}

/**
 * Tells a parent's assignee once its last open sub-issue (at any depth) is
 * closed. Only the direct parent is considered; archiving a sub-issue never
 * walks further up than that.
 */
async function notifyIfParentHasNoOpenSubIssues(
  actor: Actor,
  orgId: OrgId,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const all = await issueRepo.listAllInProject(orgId, parent.projectId);
  const live = all.filter((issue) => issue.archivedAt === null);
  const descendants = collectDescendants(parentId, live);
  if (descendants.length === 0) return;

  const hasOpen = descendants.some(
    (issue) => !CLOSED_ISSUE_STATUSES.includes(issue.status),
  );
  if (hasOpen) return;

  await emit("issue.sub_issues_completed", {
    ...actorEnvelope(actor),
    issueId: parent.id,
    projectId: parent.projectId,
    assigneeId: parent.assigneeId,
  });
}

