/**
 * Places, moves or roots an issue. The whole subtree below it travels along,
 * so the move is judged by where the deepest descendant would land.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    await assertValidParentPlacement(
      input.orgId,
      issue.projectId,
      input.parentId,
      issue.id,
    );
  }

  if (issue.parentId === input.parentId) {
    return issue;
  }

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

